    // named places ({ n: HUD label, d: metres after the start line, say: the commentator's lines })
    names: [
      {"n":"Pauma Valley","d":30.0,"say":["Away from Pauma Valley, and straight up the mountain!","The orange groves of Pauma Valley behind you, the climb begins!"]},
      {"n":"Serpentina 1 · 882 m","d":394.0,"say":["Hairpin one! Thirteen of them on the way up!","The first hairpin, and the real climb starts here!"]},
      {"n":"Serpentina 2 · 910 m","d":765.9},
      {"n":"Serpentina 3 · 931 m","d":1057.9},
      {"n":"Serpentina 4 · 969 m","d":1647.8},
      {"n":"Serpentina 5 · 1.002 m","d":2061.8},
      {"n":"Serpentina 6 · 1.057 m","d":2851.7,"say":["Hairpin six, halfway through the ladder!","Hairpin six, the valley dropping away below!"]},
      {"n":"Serpentina 7 · 1.076 m","d":3111.7},
      {"n":"Serpentina 8 · 1.094 m","d":3403.7},
      {"n":"Postajališče · 1.129 m","d":3873.6,"say":["Past the turnout, the whole valley spread out below!","The turnout on the left, riders stopping for the view!"]},
      {"n":"Serpentina 9 · 1.142 m","d":4103.6},
      {"n":"Serpentina 10 · 1.166 m","d":4409.6},
      {"n":"Serpentina 11 · 1.198 m","d":4851.5,"say":["Hairpin eleven, into the oaks and the pines now!","Hairpin eleven, the air is getting cooler up here!"]},
      {"n":"Serpentina 12 · 1.388 m","d":7293.2},
      {"n":"Serpentina 13 · 1.421 m","d":7801.2,"say":["The last hairpin! Flat out to the top!","Hairpin thirteen, the last of them!"]},
      {"n":"Palomar Mountain · 1.435 m","d":7990.2,"say":["Up on Palomar Mountain! Thirteen hairpins conquered!","The top of the grade! What a climb up Palomar!"]},
    ],
    // the commentator's own lines on this road (Comm: instead of Vršič's)
    comm: {
      introPass: ["Welcome to {track}! Thirteen cars, eight kilometres and thirteen hairpins up the South Grade, and you start {grid}.", "Here we are at the foot of {track}. Hairpin after hairpin to the top, and you line up {grid}.", "Welcome to the mountain above Pauma Valley, and to {track}! Thirteen cars, one grade, and you start {grid}."],
      goPass: ["Lights out, and away they go, up the mountain!", "And they're off! Thirteen hairpins to the top!", "Green light! The pack charges up the grade!", "Go, go, go! Next stop, the top of the grade!"],
      introPassTT: ["Welcome to {track}! Eight kilometres of hairpins, just you and the clock.", "Here we are at the foot of {track}. {cps} checkpoints between you and the top.", "Welcome to {track}! No rivals this time, only the clock and the hairpins."],
      goPassTT: ["Green light! The clock is running!", "Go! Attack the hairpins!", "And you're away! Up the South Grade!"],
      introTraffic: ["Welcome to {track}, and the road is open today: cars, riders and cyclists both ways. Just you and {rival}, first to the top wins!", "Here we are at the foot of {track}. A duel with {rival} through the traffic on the hairpins. Watch out for the cyclists on the climb!", "Welcome to {track}! No closed road this time: riders leaning through every hairpin. Beat {rival} to the top!"],
      introPolice: ["Welcome to {track}! The police want a word with you, and they are right behind. Get to the top without getting caught!", "Here we are at the foot of the mountain, and the lights are already flashing. Eight kilometres of hairpins to the top. Do not stop!", "Welcome to {track}! A patrol car on your tail, spike strips and roadblocks up the grade. Run for it!"],
      escaped: ["You made it to the top! The police will have to wait for another day!", "Escaped! Up the hairpins and away!", "What a getaway! Every hairpin of the grade!"],
      summitRecord: ["At the top! A new personal best, {time}!", "Record run! {time} up the hairpins!", "What a climb! New personal best, {time}!"],
      summitEven: ["At the top in {time}. That is your record to the thousandth!", "{time} at the top, dead level with your best!"],
      summit: ["At the top in {time}, {delta} seconds off your best.", "Across the line at the top. {time}, just {delta} short of the record.", "That's the top. {time}. {delta} seconds to find next time."],
    },
